head.b:skin:
/* Reset and Global Styles */
* { margin: 0; padding: 0; box-sizing: border-box; }
body { font-family: 'Inter', sans-serif; color: #374151; background: #f9fafb; }
h1, h2, h3, h4, h5, h6 { font-family: 'Nunito', sans-serif; }
.main-section { min-height: 100vh; }
.transition-all { transition: all 0.3s ease; }
.animation-delay-2000 { animation-delay: 2s; }
.animation-delay-4000 { animation-delay: 4s; }
.status-msg-wrap { display: none !important; }
.blog-pager { display: none !important; }
.quickedit { display: none !important; }
#navbar-iframe { display: none !important; }
/* Ticker Animation */
@keyframes aspire-ticker { 0% { transform: translateX(100%); } 100% { transform: translateX(-100%); } }
.ticker-wrap { overflow: hidden; width: 100%; }
.ticker-content { display: inline-block; white-space: nowrap; animation: aspire-ticker 30s linear infinite; }
.ticker-content:hover { animation-play-state: paused; }
/* Nav underline hover */
.nav-link-hover { position: relative; }
.nav-link-hover::after { content: ''; position: absolute; bottom: -4px; left: 0; width: 0; height: 2px; background: #F26722; transition: width 0.25s; }
.nav-link-hover:hover::after { width: 100%; }

head.script:
//
tailwind.config = {
  darkMode: 'class',
  theme: {
    extend: {
      colors: {
        primary: {
          DEFAULT: '#F26722',
          hover: '#d95a1c',
        },
        secondary: {
          DEFAULT: '#4F46E5',
          hover: '#4338ca',
        },
        accent: {
          DEFAULT: '#FBBF24',
        }
      },
      fontFamily: {
        sans: ['Inter', 'sans-serif'],
        heading: ['Nunito', 'sans-serif'],
      },
      animation: {
        'blob': 'blob 7s infinite',
      },
      keyframes: {
        blob: {
          '0%': { transform: 'translate(0px, 0px) scale(1)' },
          '33%': { transform: 'translate(30px, -50px) scale(1.1)' },
          '66%': { transform: 'translate(-20px, 20px) scale(0.9)' },
          '100%': { transform: 'translate(0px, 0px) scale(1)' },
        }
      }
    }
  }
}
//

//
  const SUPABASE_URL = 'https://mhwszwdhyluraydnexyn.supabase.co';
  const SUPABASE_ANON_KEY = 'sb_publishable_jZFjyR57wQumHEQ8pjFPRg_zZh8PMp0';
  const { createClient } = supabase;
  const supabaseClient = createClient(SUPABASE_URL, SUPABASE_ANON_KEY);

  // Global State for Dynamic Content
  window.appData = {
    settings: {},
    team: [],
    facilities: [],
    events: [],
    blogs: [],
    testimonials: [],
    stats: []
  };

  async function fetchAppData() {
    try {
      // Fetch ALL data in parallel for performance
      const [settingsRes, teamRes, facRes, eventsRes, blogsRes, testimonialsRes, statsRes] = await Promise.all([
        supabaseClient.from('school_settings').select('*'),
        supabaseClient.from('team_members').select('*').order('display_order', { ascending: true }),
        supabaseClient.from('facilities').select('*').order('display_order', { ascending: true }),
        supabaseClient.from('events').select('*').order('event_date', { ascending: true }),
        supabaseClient.from('blogs').select('*').order('created_at', { ascending: false }),
        supabaseClient.from('testimonials').select('*').order('display_order', { ascending: true }),
        supabaseClient.from('stats').select('*').order('display_order', { ascending: true })
      ]);

      // Settings
      if (settingsRes.data) {
        settingsRes.data.forEach(s => window.appData.settings[s.key] = s.value);
      }

      // People & Facilities
      if (teamRes.data) window.appData.team = teamRes.data;
      if (facRes.data) window.appData.facilities = facRes.data;

      // Content
      if (eventsRes.data) window.appData.events = eventsRes.data;
      if (blogsRes.data) window.appData.blogs = blogsRes.data;
      if (testimonialsRes.data) window.appData.testimonials = testimonialsRes.data;
      if (statsRes.data) window.appData.stats = statsRes.data;

      // Trigger UI Update — all data ready
      document.dispatchEvent(new CustomEvent('appDataLoaded'));
    } catch (err) {
      console.error('Error fetching dynamic data:', err);
      // Still trigger event so static fallbacks show
      document.dispatchEvent(new CustomEvent('appDataLoaded'));
    }
  }

  document.addEventListener('DOMContentLoaded', fetchAppData);
//

//
  // Handle Dark Mode Init to prevent flash
  if (localStorage.getItem('theme') === 'dark' || (!('theme' in localStorage) && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
      document.documentElement.classList.add('dark');
  } else {
      document.documentElement.classList.remove('dark');
  }
//

body.script:
/*  */
(function() {
  var url = window.location.href;
  if (url.indexOf('?m=1') !== -1 || url.indexOf('&m=1') !== -1) {
    window.location.replace(url.replace(/[?&]m=1/g, function(match) {
      return match.charAt(0) === '?' ? '?m=0' : '&m=0';
    }));
  }
})();
/*  */

div.script:
//
/* Mobile Menu Toggle */
function toggleAspireMenu() {
    var m = document.getElementById('aspireMenu');
    if (m.style.display === 'flex' || m.style.display === 'block') {
        m.style.display = 'none';
    } else {
        m.style.display = 'flex';
        m.style.flexDirection = 'column';
    }
}

/* Dark Mode Toggle */
function toggleTheme() {
    if (document.documentElement.classList.contains('dark')) {
        document.documentElement.classList.remove('dark');
        localStorage.setItem('theme', 'light');
    } else {
        document.documentElement.classList.add('dark');
        localStorage.setItem('theme', 'dark');
    }
}
document.addEventListener('DOMContentLoaded', function() {
    var desktopBtn = document.getElementById('theme-toggle-desktop');
    var mobileBtn = document.getElementById('theme-toggle-mobile');
    if (desktopBtn) desktopBtn.addEventListener('click', toggleTheme);
    if (mobileBtn) mobileBtn.addEventListener('click', toggleTheme);
});

/* Fetch latest posts for topbar ticker */
document.addEventListener('DOMContentLoaded', function() {
    fetch('/feeds/posts/default?alt=json&max-results=6')
        .then(function(r) { return r.json(); })
        .then(function(data) {
            var entries = (data.feed && data.feed.entry) ? data.feed.entry : [];
            if (!entries.length) return;
            var ticker = document.getElementById('aspireTicker');
            var html = entries.map(function(e) {
                var title = e.title ? e.title.$t : '';
                var linkObj = e.link ? e.link.find(function(l) { return l.rel === 'alternate'; }) : null;
                var url = linkObj ? linkObj.href + '?m=0' : '#';
                return '<a href="' + url + '" style="color:rgba(255,255,255,0.92);text-decoration:none;font-weight:600;margin-right:56px;">' + title + '</a><span style="margin-right:56px;opacity:0.35">&#183;</span>';
            }).join('');
            ticker.innerHTML = html;
        })
        .catch(function() {});
});
//

b:if.script:
//
  document.addEventListener('appDataLoaded', function() {
    var s = window.appData.settings;
    if (!s) return;
    document.getElementById('dyn-welcome-title').innerText = s.welcome_title || 'Welcome to Aspire School';
    document.getElementById('dyn-welcome-msg1').innerText = s.welcome_message_1 || '';
    document.getElementById('dyn-welcome-msg2').innerText = s.welcome_message_2 || '';
    document.getElementById('dyn-director-name').innerText = s.director_name || 'Mr. Deepak Kumar Vidyarthi';
    if (s.director_image_url) document.getElementById('dyn-director-img').src = s.director_image_url;
  });
//

//
  document.addEventListener('appDataLoaded', function() {
    var dict = window.appData.stats;
    if (!dict || !dict.length) return;
    document.getElementById('stats-container').innerHTML = dict.map(function(stat) {
        var icon = stat.icon || 'trophy';
        return '<div class="flex flex-col items-center text-center"><div class="flex items-center justify-center w-16 h-16 mb-4 rounded-full bg-blue-500 bg-opacity-50"><i data-lucide="' + icon + '" class="w-8 h-8 text-white"></i></div><div class="text-4xl font-extrabold text-white mb-2"><span>' + stat.value + '</span>' + (stat.suffix||'') + '</div><div class="text-lg font-medium text-blue-100">' + stat.label + '</div></div>';
    }).join('');
    if (typeof lucide !== 'undefined') lucide.createIcons();
  });
//

//
  document.addEventListener('appDataLoaded', function() {
    var list = document.getElementById('dyn-events-list');
    if (!list || !window.appData.events) return;
    var latestEvents = window.appData.events.slice(0, 3);
    list.innerHTML = latestEvents.map(function(ev) {
      var d = new Date(ev.event_date);
      var dStr = d.toLocaleDateString('en-US', { day: 'numeric', month: 'short' });
      var img = ev.image_url || 'https://images.unsplash.com/photo-1523580494863-6f3031224c94?w=400';
      return '<div class="bg-white rounded-3xl overflow-hidden border border-slate-100 shadow-lg hover:shadow-xl transition-shadow group"><div class="h-48 overflow-hidden relative"><img src="' + img + '" class="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"/><div class="absolute bottom-4 left-4 bg-white/90 backdrop-blur-sm px-3 py-1 rounded-lg text-primary font-bold text-xs flex items-center gap-1 shadow-sm"><i data-lucide="calendar" class="w-3.5 h-3.5"></i> ' + dStr + '</div></div><div class="p-6"><h4 class="font-bold text-slate-800 mb-2 line-clamp-1">' + ev.title + '</h4><p class="text-slate-500 text-sm line-clamp-2 mb-4">' + ev.description + '</p><a href="/p/events.html" class="text-primary text-xs font-bold uppercase tracking-wider hover:underline flex items-center gap-1">Learn More <i data-lucide="arrow-right" class="w-3.5 h-3.5"></i></a></div></div>';
    }).join('');
    if (typeof lucide !== 'undefined') lucide.createIcons();
  });
//

//
  document.addEventListener('appDataLoaded', function() {
    var container = document.getElementById('dyn-testimonial-container');
    if (!container || !window.appData.testimonials || window.appData.testimonials.length === 0) return;

    var testimonials = window.appData.testimonials;
    var currentIndex = 0;

    var renderTestimonial = function(index) {
      var t = testimonials[index];
      var starsHtml = '';
      for (var i = 0; i < t.rating; i++) {
        starsHtml += '<i data-lucide="star" class="w-5 h-5 fill-current border-none"></i>'; // Lucide native fill is tough, let's use standard star
      }

      var html = '<div class="bg-slate-50 rounded-3xl p-8 md:p-12 shadow-xl border border-slate-100 flex flex-col items-center text-center animate-fade-in"><div class="bg-primary/10 p-4 rounded-full mb-8"><i data-lucide="quote" class="w-8 h-8 text-primary"></i></div><div class="flex gap-1 text-yellow-400 mb-6">' + starsHtml + '</div><p class="text-xl md:text-2xl text-slate-700 leading-relaxed italic mb-10">&quot;' + t.content + '&quot;</p><div class="flex items-center gap-4"><div class="w-16 h-16 rounded-full overflow-hidden border-4 border-white shadow-md"><img src="' + (t.image_url || 'https://ui-avatars.com/api/?name=' + encodeURIComponent(t.name)) + '" alt="' + t.name + '" class="w-full h-full object-cover"/></div><div class="text-left"><h4 class="font-bold text-slate-900 text-lg">' + t.name + '</h4><p class="text-primary text-sm font-semibold uppercase tracking-wider">' + t.role + '</p></div></div></div>';

      // Controls
      html += '<div class="flex justify-center gap-4 mt-12"><button id="test-prev" class="p-3 rounded-full bg-white shadow-md border border-slate-100 text-slate-400 hover:text-primary hover:border-primary transition-all"><i data-lucide="chevron-left" class="w-6 h-6"></i></button><div class="flex items-center gap-2">';
      for (var j = 0; j < testimonials.length; j++) {
        var active = j === index ? 'w-8 bg-primary' : 'w-2 bg-slate-200';
        html += '<button data-index="' + j + '" class="h-2 rounded-full transition-all test-dot ' + active + '"></button>';
      }
      html += '</div><button id="test-next" class="p-3 rounded-full bg-white shadow-md border border-slate-100 text-slate-400 hover:text-primary hover:border-primary transition-all"><i data-lucide="chevron-right" class="w-6 h-6"></i></button></div>';

      container.innerHTML = html;
      if (typeof lucide !== 'undefined') lucide.createIcons();

      document.getElementById('test-prev').addEventListener('click', function() {
        currentIndex = (currentIndex - 1 + testimonials.length) % testimonials.length;
        renderTestimonial(currentIndex);
        resetTimer();
      });
      document.getElementById('test-next').addEventListener('click', function() {
        currentIndex = (currentIndex + 1) % testimonials.length;
        renderTestimonial(currentIndex);
        resetTimer();
      });
      document.querySelectorAll('.test-dot').forEach(function(dot) {
        dot.addEventListener('click', function(e) {
          currentIndex = parseInt(e.target.getAttribute('data-index'));
          renderTestimonial(currentIndex);
          resetTimer();
        });
      });
    };

    renderTestimonial(0);

    var timer;
    var resetTimer = function() {
      clearInterval(timer);
      timer = setInterval(function() {
        currentIndex = (currentIndex + 1) % testimonials.length;
        renderTestimonial(currentIndex);
      }, 5000);
    };
    resetTimer();
  });
//

div.script:
//
  document.addEventListener('appDataLoaded', function() {
    var s = window.appData.settings;
    if (s.school_address) document.getElementById('dyn-footer-address').innerText = s.school_address;
    if (s.school_phone) {
      document.getElementById('dyn-footer-phone').innerText = s.school_phone;
      document.getElementById('dyn-footer-phone').href = 'tel:' + s.school_phone;
    }
    if (s.school_email) {
      document.getElementById('dyn-footer-email').innerText = s.school_email;
      document.getElementById('dyn-footer-email').href = 'mailto:' + s.school_email;
    }

    var social = document.getElementById('dyn-footer-social');
    var links = [
      { icon: 'facebook', url: s.social_facebook },
      { icon: 'instagram', url: s.social_instagram },
      { icon: 'twitter', url: s.social_twitter },
      { icon: 'youtube', url: s.social_youtube }
    ];
    social.innerHTML = links.filter(function(l) { return l.url; }).map(function(l) {
      return '<a href="' + l.url + '" class="w-12 h-12 bg-white/5 rounded-2xl flex items-center justify-center text-gray-400 hover:bg-primary hover:text-white transition-all transform hover:-translate-y-1"><i data-lucide="' + l.icon + '" class="w-5 h-5"></i></a>';
    }).join('');
    if (typeof lucide !== 'undefined') lucide.createIcons();
  });
//
